using System;using System.IO;using System.Linq;using System.Threading;using System.Security.Principal;using SargasPC;
public class CaseReview {
 public static volatile Core ActiveCore;public static void Cancel(){var c=ActiveCore;if(c!=null)c.Cancelled=true;}
 public sealed class Case {public string Id,Directory,Report,State,VaultId,VaultOwnerSid,ReviewedFile,ReviewedHash,Review;public long At,ReviewedAt;public int VaultProfileKind;}
 static string Value(string[] args,string key){int i=Array.IndexOf(args,key);return i>=0&&i+1<args.Length?args[i+1]:null;}
 static void Save(string path,Case c){c.ReviewedAt=DateTime.UtcNow.Ticks;Data.Atomic(path,Data.Json().Serialize(c));}
 [STAThread]static int Main(string[] args){if(Environment.OSVersion.Platform!=PlatformID.Win32NT)return 2;if(Array.IndexOf(args,"--gui")>=0){System.Windows.Forms.Application.EnableVisualStyles();System.Windows.Forms.Application.SetCompatibleTextRenderingDefault(false);System.Windows.Forms.Application.Run(new CaseReviewWindow());return 0;}Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;Cancel();};return Execute(args);}
 public static int Execute(string[] args){string id=Value(args,"--case"),action=Value(args,"--action")??"check";if(id==null||id.Length!=32||id.Any(c=>!Uri.IsHexDigit(c))||!new[]{"check","quarantine","restore"}.Contains(action)){Console.WriteLine("--case <32hex> --action check|quarantine|restore --file <path> [--destination <new-file>]");return 2;}
 using(var mutex=new Mutex(false,"Local\\SARGONCaseReview_v1")){bool held=false;Mutex legacy=null;bool legacyHeld=false;try{held=mutex.WaitOne(0);if(!held)throw new IOException("Kitas radinių peržiūros veiksmas jau vyksta. Palaukite jo pabaigos.");string recordPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SARGONService","Private","cases",id+".json");FolderMonitor.NoLinks(recordPath);var record=Data.Read<Case>(recordPath,131072);if(record==null||record.Id!=id||string.IsNullOrEmpty(record.Directory))throw new IOException("Radinio įrašas nepatvirtintas.");
 string profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),action=="restore"&&record.VaultProfileKind==0?"TelefonoSargasPC":"SARGONCaseReview");
 if(action=="restore"&&record.VaultProfileKind==0){legacy=new Mutex(false,"Local\\SargasPC_v1");legacyHeld=legacy.WaitOne(0);if(!legacyHeld)throw new IOException("Senos kopijos atkūrimui pirmiausia užbaikite seną vartotojo GUI.");}
 var core=new Core(profile);ActiveCore=core;core.EngineBinaryDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"SARGONService","engine","clamav-1.4.6.win.x64");core.EngineDatabaseDirectory=SharedEngine.DatabasePath();string sid=WindowsIdentity.GetCurrent().User.Value;
 if(action=="restore"){
  if(record.VaultOwnerSid!=sid||record.VaultId==null)throw new IOException("Kopija priklauso kitai paskyrai arba jos ID nepatvirtintas.");var entry=core.Vault().SingleOrDefault(x=>x.Id==record.VaultId);if(entry==null)throw new IOException("Kopija nerasta.");string destination=Value(args,"--destination");if(string.IsNullOrEmpty(destination))throw new IOException("Reikia naujo atkūrimo failo kelio.");FolderMonitor.NoLinks(Path.GetDirectoryName(Path.GetFullPath(destination)));core.Restore(entry,destination);core.Reset();var restored=core.Scan(destination);record.Review=core.ScanLocalEngine(restored);record.State=core.EngineFindings>0?"RESTORED_STILL_DETECTED":core.NotChecked>0?"RESTORED_RECHECK_INCOMPLETE":"RESTORED_NO_SIGNATURES";record.ReviewedFile=Path.GetFullPath(destination);record.ReviewedHash=restored.Hash;Save(recordPath,record);Console.WriteLine(record.State+"\r\n"+record.Review+"\r\nAtkūrimas nėra saugumo garantija; kopija palikta.");return 0;
 }
 string file=Value(args,"--file");if(string.IsNullOrEmpty(file))throw new IOException("Nurodykite konkretų radinio failą iš ataskaitos.");file=Path.GetFullPath(file);if(!string.Equals(Path.GetDirectoryName(file).TrimEnd(Path.DirectorySeparatorChar),Path.GetFullPath(record.Directory).TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new IOException("Failas nepriklauso šio radinio aplanko lygiui.");var w=core.Scan(file);record.Review=core.ScanLocalEngine(w);record.ReviewedFile=file;record.ReviewedHash=w.Hash;record.State=w.Kind=="ENGINE"?"DETECTION_CONFIRMED":w.Test?"TEST_MARKER":core.NotChecked>0?"CHECK_INCOMPLETE":"NO_SIGNATURES_ON_RECHECK";Save(recordPath,record);
 if(action=="quarantine"){
  if(w.Kind!="ENGINE"||w.Test||core.NotChecked>0)throw new IOException("Automatinis veiksmas neleidžiamas: reikia naujo pilno vietinio variklio radinio, ne bandymo žymens.");var prior=core.Vault().Select(x=>x.Id).ToArray();record.State="QUARANTINE_PENDING";Save(recordPath,record);try{record.Review+="\r\n"+core.IsolateAndConfirm(w);var added=core.Vault().Where(x=>!prior.Contains(x.Id)).ToArray();if(added.Length==1){record.VaultId=added[0].Id;record.VaultOwnerSid=sid;record.VaultProfileKind=1;}record.State=core.VisualEvent=="REMOVAL_CONFIRMED"?"ORIGINAL_ISOLATED":"QUARANTINE_UNCONFIRMED";}catch(Exception e){record.State="QUARANTINE_UNCONFIRMED";record.Review+="\r\n"+Data.Diagnostic(e);Save(recordPath,record);throw;}Save(recordPath,record);
 }
 Console.WriteLine(record.State+"\r\n"+record.Review+"\r\nRezultatas taikomas vienam failui, ne veikiančiam procesui ar visam kompiuteriui.");return 0;
 }catch(Exception e){Console.WriteLine("NEPATVIRTINTA: "+Data.Diagnostic(e));return 1;}finally{ActiveCore=null;if(legacyHeld)legacy.ReleaseMutex();if(legacy!=null)legacy.Dispose();if(held)mutex.ReleaseMutex();}}
 }
}
